from pathlib import Path
from openpyxl import load_workbook
base=Path('/workspace/inputs')
out=Path('/workspace/galaxy_staging_asxl1')
out.mkdir(exist_ok=True)
wb=load_workbook(base/'Issy_ASXL1_blood_coldata_gender.xlsx', read_only=True, data_only=True)
ws=wb.active
rows=list(ws.iter_rows(values_only=True))
headers=[str(x) for x in rows[0]]
meta={str(r[0]): {'condition':str(r[1]), 'sex':str(r[2])} for r in rows[1:] if r[0] is not None}
with (base/'Issy_ASXL1_blood_featureCounts_GeneTable_final.txt').open() as f:
 count_header=f.readline().split()
 samples=count_header[1:]
 if set(samples)"'!=set(meta):
  raise SystemExit(f'"'sample mismatch counts_only={sorted(set(samples)-set(meta))} metadata_only={sorted(set(meta)-set(samples))}')
 handles={s:(out/f'{s}.counts.tsv').open('w') for s in samples}
 try:
  for h in handles.values(): h.write('Geneid\\tCount\\n')
  n=0
  seen=set()
  for line in f:
   fields=line.split()
   if len(fields)"'!=len(count_header): raise SystemExit(f'"'row {n+2}: expected {len(count_header)} fields, got {len(fields)}')
   gene=fields[0]
   if gene in seen: raise SystemExit(f'duplicate Geneid: {gene}')
   seen.add(gene)
   for s,v in zip(samples,fields[1:]):
    if not v.isdigit(): raise SystemExit(f'noninteger count {gene} {s} {v}')
    handles[s].write(f'{gene}\\t{v}\\n')
   n+=1
 finally:
  for h in handles.values(): h.close()
print('samples',len(samples),'genes',n)
print('condition_counts', {k:sum(v['condition']==k for v in meta.values()) for k in sorted({v['condition'] for v in meta.values()})})
print('sex_counts', {k:sum(v['sex']==k for v in meta.values()) for k in sorted({v['sex'] for v in meta.values()})})
for s in samples: print(s,meta[s]['condition'],meta[s]['sex'])
PY"

